const KEY="WSM9";
const OLD_KEY="WSM8";
const questions=[
 "What's your worst food?","Who is your celebrity crush?","What's your biggest fear?","What's your dream destination?","What's your favourite colour?","What's your hidden talent?","What food could you eat every day?","What's your biggest pet peeve?","Who is your favourite musician?","What's one thing you really want to achieve?"
];
const blank=()=>({profiles:{},quizzes:{},attempts:[],memories:[],notifications:[],following:[],friendRequests:[],puzzleGames:{}});
function load(){try{const x=JSON.parse(localStorage.getItem(KEY));if(x)return x;const old=JSON.parse(localStorage.getItem(OLD_KEY));if(old){const migrated={...blank(),...old};localStorage.setItem(KEY,JSON.stringify(migrated));return migrated}return blank()}catch(e){return blank()}}
let db=load();
let current=localStorage.getItem("WSM9_CURRENT")||localStorage.getItem("WSM8_CURRENT")||"";
let memoryFiles=[];let pendingAvatar="";let feedMode="forYou";let discoverMode="people";
function save(){localStorage.setItem(KEY,JSON.stringify(db))}
function esc(s=""){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function initials(name=""){return name.trim().split(/\s+/).slice(0,2).map(x=>x[0]).join("").toUpperCase()||"?"}
function avatar(p,cls=""){return p?.avatar?`<div class="avatar ${cls}"><img src="${p.avatar}" alt=""></div>`:`<div class="avatar ${cls}">${esc(initials(p?.displayName||p?.username))}</div>`}
function me(){return db.profiles[current]}
function toast(msg){const t=document.getElementById("toast");t.textContent=msg;t.classList.add("show");clearTimeout(window.__toast);window.__toast=setTimeout(()=>t.classList.remove("show"),1900)}
function timeAgo(ts){const s=Math.max(1,Math.floor((Date.now()-ts)/1000));if(s<60)return `${s}s`;const m=Math.floor(s/60);if(m<60)return `${m}m`;const h=Math.floor(m/60);if(h<24)return `${h}h`;const d=Math.floor(h/24);return d<7?`${d}d`:new Date(ts).toLocaleDateString(undefined,{month:"short",day:"numeric"})}
function go(id){document.querySelectorAll(".screen").forEach(s=>s.classList.toggle("active",s.id===id));document.querySelectorAll(".bottom-nav button").forEach(b=>b.classList.toggle("active",b.dataset.go===id));if(id==="home")renderHome();if(id==="discover")renderDiscover();if(id==="profile")renderMyProfile();if(id==="memory")renderMemories();if(id==="notifications")renderNotifications();if(id==="puzzle")renderPuzzleHub();window.scrollTo({top:0,behavior:"smooth"})}
document.querySelectorAll("[data-go]").forEach(b=>b.addEventListener("click",()=>go(b.dataset.go)));

function makeQuestions(){document.getElementById("questions").innerHTML=questions.map((q,i)=>`<div class="question"><strong>${i+1}. ${esc(q)}</strong><input data-q="${i}" maxlength="100" placeholder="Your answer"></div>`).join("")}
makeQuestions();

function profileAvatarPreview(src){document.getElementById("profileAvatarBtn").innerHTML=src?`<img src="${src}" alt="">`:`+`}
document.getElementById("profileAvatarBtn").onclick=()=>document.getElementById("profileAvatar").click();
document.getElementById("profileAvatar").onchange=e=>{const f=e.target.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{pendingAvatar=r.result;profileAvatarPreview(pendingAvatar)};r.readAsDataURL(f)};

function createQuiz(){
 const username=document.getElementById("username").value.trim().toLowerCase().replace(/[^a-z0-9_.-]/g,"");
 const displayName=document.getElementById("displayName").value.trim()||username;
 const bio=document.getElementById("bio").value.trim();
 if(!username){toast("Choose a username first");return}
 if(username.length<3){toast("Username needs at least 3 characters");return}
 const answers=[...document.querySelectorAll("[data-q]")].map(x=>x.value.trim());
 if(answers.some(x=>!x)){toast("Answer all 10 questions");return}
 const existing=db.profiles[username]||{};
 db.profiles[username]={username,displayName,bio,createdAt:existing.createdAt||Date.now(),avatar:pendingAvatar||existing.avatar||""};
 db.quizzes[username]={username,answers,questions,createdAt:Date.now()};
 current=username;localStorage.setItem("WSM9_CURRENT",current);save();updateChrome();
 toast("Profile and quiz saved!");renderProfile(username);go("profile");
}
document.getElementById("createBtn").onclick=createQuiz;

function quizUrl(u){return `${location.href.split("#")[0]}#quiz=${encodeURIComponent(u)}`}
function shareText(u){return `WHO SABI ME? 🔥\nLet's see if you really know me. Take my quiz: ${quizUrl(u)}`}
async function shareQuiz(u){const text=shareText(u);if(navigator.share){try{await navigator.share({title:"WHO SABI ME?",text,url:quizUrl(u)});return}catch(e){}}try{await navigator.clipboard.writeText(text);toast("Quiz message copied")}catch(e){window.open("https://wa.me/?text="+encodeURIComponent(text),"_blank")}}
async function shareApp(){const text="Try WHO SABI ME? — create a quiz and find out who really knows you.";if(navigator.share){try{await navigator.share({title:"WHO SABI ME?",text,url:location.href.split("#")[0]});return}catch(e){}}try{await navigator.clipboard.writeText(text+" "+location.href.split("#")[0]);toast("App link copied")}catch(e){toast("Share is not available")}}
document.getElementById("shareAppBtn").onclick=shareApp;

function profileCard(p){return `<button class="profile-card" onclick="renderProfile('${esc(p.username)}');go('profile')">${avatar(p)}<h3>${esc(p.displayName)}</h3><p>@${esc(p.username)}</p><p>${esc(p.bio||"WHO SABI ME? player")}</p></button>`}
function renderDiscover(filter=""){const list=Object.values(db.profiles).filter(p=>(p.username+" "+p.displayName+" "+(p.bio||"")).toLowerCase().includes(filter.toLowerCase()));const box=document.getElementById("discoverList");if(discoverMode==="people"){box.innerHTML=list.length?`<div class="profile-grid">${list.map(profileCard).join("")}</div>`:`<div class="empty">No people found yet.</div>`}else if(discoverMode==="memories"){const mem=db.memories.filter(m=>(m.caption||"").toLowerCase().includes(filter.toLowerCase())).sort((a,b)=>b.createdAt-a.createdAt);box.innerHTML=mem.length?`<div class="feed">${mem.map(memoryCard).join("")}</div>`:`<div class="empty">No matching memories.</div>`}else{const quizzes=Object.values(db.quizzes).filter(q=>{const p=db.profiles[q.username];return (q.username+" "+(p?.displayName||"")).toLowerCase().includes(filter.toLowerCase())});box.innerHTML=quizzes.length?quizzes.map(q=>{const p=db.profiles[q.username];return `<div class="result-card">${avatar(p)}<div><b>${esc(p.displayName)}</b><small>@${esc(p.username)} • 10 questions</small></div><button class="quiz-badge" onclick="location.hash='quiz=${encodeURIComponent(q.username)}'">Play</button></div>`}).join(""):`<div class="empty">No quizzes found.</div>`}}
document.getElementById("searchInput").addEventListener("input",e=>renderDiscover(e.target.value));
document.querySelectorAll("[data-discover]").forEach(b=>b.addEventListener("click",()=>{discoverMode=b.dataset.discover;document.querySelectorAll("[data-discover]").forEach(x=>x.classList.toggle("active",x===b));renderDiscover(document.getElementById("searchInput").value)}));

function storyList(){const profiles=Object.values(db.profiles);return profiles.length?profiles.slice(0,12).map(p=>`<button class="story" onclick="renderProfile('${esc(p.username)}');go('profile')"><div class="story-ring">${avatar(p)}</div><span>${esc(p.username)}</span></button>`).join(""):``}
function renderHome(){
 document.getElementById("stories").innerHTML=storyList();
 const all=[...db.memories].sort((a,b)=>b.createdAt-a.createdAt);
 let list=all;
 if(feedMode==="following")list=all.filter(m=>m.username===current||db.following.includes(m.username));
 if(feedMode==="quiz"){const quizPosts=db.attempts.slice().sort((a,b)=>b.createdAt-a.createdAt);document.getElementById("homeFeed").innerHTML=quizPosts.length?quizPosts.slice(0,12).map(attemptCard).join(""):`<div class="empty">Quiz activity will appear here after people play.</div>`;return}
 document.getElementById("homeFeed").innerHTML=list.length?list.slice(0,12).map(memoryCard).join(""):`<div class="empty">Your feed is waiting for its first throwback. Create a profile, then post a memory.</div>`;
 updateHomeAvatar();
}
document.querySelectorAll("[data-feed]").forEach(b=>b.addEventListener("click",()=>{feedMode=b.dataset.feed;document.querySelectorAll("[data-feed]").forEach(x=>x.classList.toggle("active",x===b));renderHome()}));

function attemptCard(a){const p=db.profiles[a.username]||{username:a.username,displayName:a.username};return `<article class="feed-card"><div class="post-head">${avatar(p)}<div class="post-meta"><b>${esc(a.player)}</b><small>played @${esc(a.username)}'s quiz • ${timeAgo(a.createdAt)}</small></div></div><div class="post-text">Scored <b>${a.score}/10</b> on ${esc(p.displayName)}'s WHO SABI ME? quiz.</div><div class="post-actions"><button class="action" onclick="location.hash='quiz=${encodeURIComponent(a.username)}'">▶ Play quiz</button><button class="action" onclick="shareQuiz('${esc(a.username)}')">↗ Share</button></div></article>`}
function memoryCard(m){const p=db.profiles[m.username]||{username:m.username,displayName:m.username};const imgs=(m.photos||[]).map(x=>`<img src="${x}" loading="lazy" alt="Throwback photo">`).join("");const r=m.reactions||{};const liked=Boolean(m.likedBy&&m.likedBy.includes(current));return `<article class="feed-card"><div class="post-head"><button class="brand-btn" style="padding:0" onclick="renderProfile('${esc(m.username)}');go('profile')">${avatar(p)}<span class="post-meta"><b>${esc(p.displayName)}</b><small>@${esc(p.username)} • ${timeAgo(m.createdAt)}</small></span></button><button class="more-btn" onclick="shareMemory('${esc(m.id)}')">⋯</button></div>${m.caption?`<div class="post-text">${esc(m.caption)}</div>`:""}<div class="memory-images ${m.photos?.length===1?"one":""}">${imgs}</div><div class="post-actions"><button class="action ${liked?"active":""}" onclick="react('${esc(m.id)}','❤️')">❤️ ${r["❤️"]||0}</button><button class="action" onclick="react('${esc(m.id)}','👍')">👍 ${r["👍"]||0}</button><button class="action" onclick="react('${esc(m.id)}','😂')">😂 ${r["😂"]||0}</button><button class="action" onclick="shareMemory('${esc(m.id)}')">↗ Share</button></div></article>`}
function react(id,r){const m=db.memories.find(x=>x.id===id);if(!m)return;m.reactions=m.reactions||{};m.likedBy=m.likedBy||[];if(r==="❤️"){const i=m.likedBy.indexOf(current);if(i>=0){m.likedBy.splice(i,1);m.reactions[r]=Math.max(0,(m.reactions[r]||1)-1)}else{m.likedBy.push(current);m.reactions[r]=(m.reactions[r]||0)+1;addNotification(m.username,"react",r)}}else{m.reactions[r]=(m.reactions[r]||0)+1;addNotification(m.username,"react",r)}save();renderMemories();renderHome();}
function addNotification(username,type,value){if(!username||username===current)return;db.notifications.unshift({id:String(Date.now())+Math.random(),username,type,value,createdAt:Date.now(),read:false});db.notifications=db.notifications.slice(0,100);}
function shareMemory(id){const m=db.memories.find(x=>x.id===id);if(!m)return;const text=`${db.profiles[m.username]?.displayName||m.username}'s throwback on WHO SABI ME? 🔥 ${location.href.split("#")[0]}#memory=${encodeURIComponent(id)}`;navigator.share?navigator.share({title:"WHO SABI ME? throwback",text}):navigator.clipboard?.writeText(text).then(()=>toast("Memory link copied"))}

function renderProfile(u){const p=db.profiles[u];if(!p){toast("Create a profile first");go("create");return}const q=db.quizzes[u];const attempts=db.attempts.filter(a=>a.username===u).sort((a,b)=>b.score-a.score);const memories=db.memories.filter(m=>m.username===u).sort((a,b)=>b.createdAt-a.createdAt);const avg=attempts.length?Math.round(attempts.reduce((s,a)=>s+a.score,0)/attempts.length):0;const isMe=u===current;document.getElementById("profileMount").innerHTML=`<div class="profile-page"><div class="profile-cover"><div class="profile-row">${avatar(p)}<div><div class="profile-name">${esc(p.displayName)}</div><div class="handle">@${esc(p.username)}</div></div></div><p>${esc(p.bio||"No bio yet. Build your quiz and let people discover you.")}</p><div class="profile-actions">${isMe?`<button onclick="openEdit()">✎ Edit profile</button><button onclick="go('memory')">＋ Throwback</button>`:`<button onclick="toggleFollow('${esc(u)}')">${db.following.includes(u)?"✓ Following":"＋ Follow"}</button>`}<button onclick="shareQuiz('${esc(u)}')">↗ Share quiz</button></div><div class="stat-row"><div class="stat"><b>${attempts.length}</b><span>Players</span></div><div class="stat"><b>${avg}%</b><span>Avg score</span></div><div class="stat"><b>${memories.length}</b><span>Memories</span></div></div></div>${q?`<div class="card form-card" style="margin-top:12px"><b>Your quiz link</b><div class="quiz-link">${esc(quizUrl(u))}</div><button class="secondary full" style="margin-top:9px" onclick="copyQuiz('${esc(u)}')">Copy quiz link</button></div>`:""}<div class="section-head"><h2>Leaderboard</h2></div><div class="card form-card">${attempts.length?attempts.slice(0,10).map((a,i)=>`<div class="leader-row"><span>${i+1}. ${esc(a.player)}</span><b>${a.score}/10</b></div>`).join(""):`<div class="empty">No one has played yet.</div>`}</div><div class="section-head"><h2>Throwbacks</h2></div><div class="feed">${memories.length?memories.map(memoryCard).join(""):`<div class="empty">No throwbacks yet.</div>`}</div></div>`}
function renderMyProfile(){if(current&&db.profiles[current])renderProfile(current);else{document.getElementById("profileMount").innerHTML=`<div class="empty">You don't have a profile yet.<br><br><button class="primary" onclick="go('create')">Create your profile</button></div>`}}
function copyQuiz(u){const url=quizUrl(u);navigator.clipboard?.writeText(url).then(()=>toast("Quiz link copied")).catch(()=>toast(url))}
function toggleFollow(u){const i=db.following.indexOf(u);if(i>=0){db.following.splice(i,1);toast("Unfollowed") }else{db.following.push(u);toast("Following @"+u)}save();renderProfile(u)}

function renderQuiz(u){const q=db.quizzes[u],p=db.profiles[u];if(!q){document.getElementById("quizMount").innerHTML=`<div class="empty">This quiz does not exist.</div>`;return}let step=0,answers=[];function draw(){if(step<10){document.getElementById("quizMount").innerHTML=`<div class="card quiz-card"><div class="small muted">${esc(p.displayName)}'s quiz</div><div class="progress"><i style="width:${((step)/10)*100}%"></i></div><div class="small muted">Question ${step+1} of 10</div><h1>${esc(q.questions[step])}</h1><input id="guess" style="width:100%;border:1px solid #ddd7e8;border-radius:13px;padding:13px;outline:none" placeholder="Your answer"><button class="primary full" style="margin-top:12px" id="nextGuess">${step===9?"Finish":"Next"}</button></div>`;document.getElementById("guess").focus();document.getElementById("nextGuess").onclick=()=>{const a=document.getElementById("guess").value.trim();if(!a){toast("Enter your guess");return}answers.push(a);step++;draw()}}else{const score=answers.reduce((n,a,i)=>n+(a.toLowerCase()===q.answers[i].toLowerCase()?1:0),0);const player=prompt("What's your name?")||"Anonymous";db.attempts.push({username:u,player,answers,score,createdAt:Date.now()});addNotification(u,"quiz",score);save();document.getElementById("quizMount").innerHTML=`<div class="card quiz-card"><div class="small muted">Your result for @${esc(u)}</div><div class="score">${score}/10</div><h2 style="text-align:center">${score===10?"You sabi this person well! 🔥":score>=7?"You sabi them! 😎":score>=4?"Not bad! 👀":"Time to study your friend 😂"}</h2><button class="primary full" onclick="shareQuiz('${esc(u)}')">Share this quiz</button><button class="secondary full" style="margin-top:8px" onclick="renderQuiz('${esc(u)}')">Try again</button></div>`}}draw()}

function openComposer(){if(!current){toast("Create a profile first");go("create");return}document.getElementById("memoryComposerPanel").classList.remove("hidden");document.getElementById("memoryCaption").focus()}
document.getElementById("composerOpen").onclick=openComposer;
document.getElementById("composerPost").onclick=async()=>{if(!current){toast("Create a profile first");go("create");return}if(!memoryFiles.length){toast("Choose at least one photo");return}const photos=await Promise.all(memoryFiles.map(file=>new Promise(res=>{const r=new FileReader();r.onload=()=>res(r.result);r.readAsDataURL(file)})));const id=crypto.randomUUID?crypto.randomUUID():String(Date.now());db.memories.unshift({id,username:current,caption:document.getElementById("memoryCaption").value.trim(),photos,reactions:{},likedBy:[],createdAt:Date.now()});save();memoryFiles=[];document.getElementById("memoryPhotos").value="";document.getElementById("memoryCaption").value="";document.getElementById("memoryPreview").innerHTML="";document.getElementById("memoryComposerPanel").classList.add("hidden");renderMemories();renderHome();toast("Throwback posted!")};
document.getElementById("memoryPhotos").onchange=e=>{memoryFiles=[...e.target.files].slice(0,6);document.getElementById("memoryComposerPanel").classList.remove("hidden");document.getElementById("memoryPreview").innerHTML=memoryFiles.map(f=>`<img src="${URL.createObjectURL(f)}" alt="preview">`).join("")};
function renderMemories(){const list=[...db.memories].sort((a,b)=>b.createdAt-a.createdAt);document.getElementById("memoryFeed").innerHTML=list.length?list.map(memoryCard).join(""):`<div class="empty">No throwbacks yet. Add your first memory above.</div>`;updateComposerAvatar()}

function renderNotifications(){const list=db.notifications.filter(n=>n.username===current);document.getElementById("notificationList").innerHTML=list.length?list.map(n=>{const p=db.profiles[n.username]||{username:n.username,displayName:n.username};const text=n.type==="react"?`Someone reacted ${n.value} to your memory.`:`Someone scored ${n.value}/10 on your quiz.`;return `<div class="notification ${n.read?"":"unread"}">${avatar(p)}<div><b>${esc(text)}</b><p>${timeAgo(n.createdAt)} ago</p></div></div>`}).join(""):`<div class="empty">No notifications yet.</div>`;list.forEach(n=>n.read=true);save();updateNotifyDot()}
function updateNotifyDot(){document.getElementById("notifyDot").classList.toggle("on",db.notifications.some(n=>n.username===current&&!n.read))}
document.getElementById("notifyBtn").onclick=()=>{go("notifications")};

function updateHomeAvatar(){const p=me();document.getElementById("homeAvatar").innerHTML=p?.avatar?`<img src="${p.avatar}" alt="">`:esc(initials(p?.displayName||p?.username||"?"))}
function updateComposerAvatar(){const p=me();document.getElementById("composerAvatar").innerHTML=p?.avatar?`<img src="${p.avatar}" alt="">`:esc(initials(p?.displayName||p?.username||"?"))}
function updateChrome(){updateHomeAvatar();updateComposerAvatar();updateNotifyDot()}

function openEdit(){const p=me();if(!p)return;document.getElementById("editName").value=p.displayName;document.getElementById("editBio").value=p.bio||"";document.getElementById("editModal").classList.remove("hidden")}
document.getElementById("closeEdit").onclick=()=>document.getElementById("editModal").classList.add("hidden");
document.getElementById("saveEdit").onclick=()=>{const p=me();p.displayName=document.getElementById("editName").value.trim()||p.username;p.bio=document.getElementById("editBio").value.trim();save();document.getElementById("editModal").classList.add("hidden");renderProfile(current);updateChrome();toast("Profile updated")};

function openSearch(){document.getElementById("searchSheet").classList.remove("hidden");document.getElementById("globalSearch").focus();renderGlobalSearch("")}
function renderGlobalSearch(term){const list=Object.values(db.profiles).filter(p=>(p.username+" "+p.displayName+" "+(p.bio||"")).toLowerCase().includes(term.toLowerCase())).slice(0,15);document.getElementById("globalSearchResults").innerHTML=list.length?list.map(p=>`<button class="result-card" style="width:100%;border:0;background:none;text-align:left" onclick="document.getElementById('searchSheet').classList.add('hidden');renderProfile('${esc(p.username)}');go('profile')">${avatar(p)}<div><b>${esc(p.displayName)}</b><small>@${esc(p.username)}</small></div></button>`).join(""):`<div class="empty">No profiles found.</div>`}
document.getElementById("searchBtn").onclick=openSearch;document.getElementById("closeSearch").onclick=()=>document.getElementById("searchSheet").classList.add("hidden");document.querySelector(".sheet-backdrop").onclick=()=>document.getElementById("searchSheet").classList.add("hidden");document.getElementById("globalSearch").oninput=e=>renderGlobalSearch(e.target.value);

function route(){const hash=location.hash;if(hash.startsWith("#quiz=")){const u=decodeURIComponent(hash.slice(6));go("join");renderQuiz(u);return}if(hash.startsWith("#memory=")){go("memory");return}if(current&&db.profiles[current])go("home");else go("home")}
window.addEventListener("hashchange",route);route();updateChrome();
if("serviceWorker" in navigator){window.addEventListener("load",()=>navigator.serviceWorker.register("sw.js").catch(()=>{}))}

/* v10 cloud accounts + cross-device sync */
let cloudUser=null;
let cloudSyncTimer=null;
let authRegister=false;
const localSave=save;
save=function(){localSave();if(cloudUser&&!window.__cloudSyncBusy){clearTimeout(cloudSyncTimer);cloudSyncTimer=setTimeout(pushCloudState,500)}};
async function api(path,opts={}){let adConfig=null;
async function loadAdConfig(){try{adConfig=await api('/api/ads/config'); if(!adConfig.enabled||!adConfig.publisherId)return; const src='https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client='+encodeURIComponent(adConfig.publisherId); if(!document.querySelector('script[data-wsm-ads]')){const sc=document.createElement('script');sc.async=true;sc.crossOrigin='anonymous';sc.src=src;sc.dataset.wsmAds='1';document.head.appendChild(sc)} setTimeout(renderConfiguredAds,700)}catch(e){console.warn('Ads unavailable',e)}}
function renderConfiguredAds(){if(!adConfig?.enabled||!adConfig.publisherId)return; document.querySelectorAll('[data-ad-slot]').forEach(w=>{const slot=w.dataset.adSlot,id='ad-'+slot,el=document.getElementById(id),slotId=adConfig.slots?.[slot];if(!el||!slotId||el.dataset.ready)return;el.innerHTML='';const ins=document.createElement('ins');ins.className='adsbygoogle';ins.style.display='block';ins.setAttribute('data-ad-client',adConfig.publisherId);ins.setAttribute('data-ad-slot',slotId);ins.setAttribute('data-ad-format','auto');ins.setAttribute('data-full-width-responsive','true');el.appendChild(ins);el.dataset.ready='1';try{(window.adsbygoogle=window.adsbygoogle||[]).push({});}catch{}; const io=new IntersectionObserver(entries=>{entries.forEach(x=>{if(x.isIntersecting){fetch('/api/ads/impression',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({slot})}).catch(()=>{});io.disconnect()}})});io.observe(el)})}
loadAdConfig();

const r=await fetch(path,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(opts.headers||{})},...opts});let data={};try{data=await r.json()}catch{}if(!r.ok)throw new Error(data.error||'Request failed');return data}
let liveEvents=null;
function setLiveStatus(on){const dot=document.getElementById('liveDot');if(dot)dot.classList.toggle('on',!!on)}
function connectLive(){if(!cloudUser||!window.EventSource)return;if(liveEvents)liveEvents.close();try{liveEvents=new EventSource('/api/events');liveEvents.onopen=()=>setLiveStatus(true);liveEvents.onerror=()=>setLiveStatus(false);liveEvents.addEventListener('notification',e=>{try{const n=JSON.parse(e.data);db.notifications.unshift(n);db.notifications=db.notifications.slice(0,1000);localSave();updateNotifyDot();}catch{}});liveEvents.addEventListener('message',e=>{try{const m=JSON.parse(e.data);db.messages=db.messages||[];db.messages.push(m);db.messages=db.messages.slice(-500);localSave();updateNotifyDot();if(document.getElementById('messages')?.classList.contains('active'))renderThread(document.getElementById('messageTo').value.trim().toLowerCase());}catch{}});liveEvents.addEventListener('comment',e=>{try{const c=JSON.parse(e.data);db.comments=db.comments||[];db.comments.push(c);localSave();if(document.getElementById('memory')?.classList.contains('active'))renderMemories();renderHome();}catch{}});liveEvents.addEventListener('friendRequest',e=>{try{const r=JSON.parse(e.data);db.friendRequests=db.friendRequests||[];db.friendRequests.push(r);localSave();}catch{}});}catch{setLiveStatus(false)}}
async function pushCloudState(){if(!cloudUser)return;try{window.__cloudSyncBusy=true;await api('/api/state',{method:'PUT',body:JSON.stringify({state:db})})}catch(e){console.warn('Cloud sync failed',e)}finally{window.__cloudSyncBusy=false}}
async function pullCloudState(){const data=await api('/api/state');if(data.state){db={...blank(),...data.state};localSave()}if(data.user){cloudUser=data.user;current=data.user.username;localStorage.setItem('WSM9_CURRENT',current)}updateChrome();renderHome()}
function setAuthMode(register){authRegister=register;document.getElementById('authTitle').textContent=register?'Create account':'Sign in';document.getElementById('authSubtitle').textContent=register?'Create a cloud account to use WHO SABI ME? on multiple devices.':'Sign in to sync your profile, quizzes and memories across devices.';document.getElementById('authSubmit').textContent=register?'Create account':'Sign in';document.getElementById('authSwitch').textContent=register?'Already have an account? Sign in':'Create an account';document.getElementById('authUsernameLabel').classList.toggle('hidden',!register);document.getElementById('authLogout').classList.toggle('hidden',!cloudUser);document.getElementById('authSubmit').classList.toggle('hidden',!!cloudUser);document.getElementById('authSwitch').classList.toggle('hidden',!!cloudUser);document.getElementById('authFields').classList.toggle('hidden',!!cloudUser);document.getElementById('authStatus').textContent=cloudUser?`Signed in as @${cloudUser.username}. Your data syncs to the server.`:''}
async function openAccount(){document.getElementById('authModal').classList.remove('hidden');setAuthMode(!!cloudUser)}
document.getElementById('accountBtn').onclick=openAccount;
document.getElementById('closeAuth').onclick=()=>document.getElementById('authModal').classList.add('hidden');
document.getElementById('authSwitch').onclick=()=>setAuthMode(!authRegister);
document.getElementById('authSubmit').onclick=async()=>{const email=document.getElementById('authEmail').value.trim();const password=document.getElementById('authPassword').value;const username=document.getElementById('authUsername').value.trim().toLowerCase().replace(/[^a-z0-9_.-]/g,'');const status=document.getElementById('authStatus');status.textContent='Working…';try{const localSnapshot=JSON.parse(JSON.stringify(db));const data=await api(authRegister?'/api/register':'/api/login',{method:'POST',body:JSON.stringify(authRegister?{email,password,username}:{email,password})});cloudUser=data.user;current=cloudUser.username;localStorage.setItem('WSM9_CURRENT',current);if(authRegister)await api('/api/state',{method:'PUT',body:JSON.stringify({state:localSnapshot})});await pullCloudState();connectLive();document.getElementById('authModal').classList.add('hidden');toast(authRegister?'Account created!':'Welcome back!');go('home')}catch(e){status.textContent=e.message}};
document.getElementById('authLogout').onclick=async()=>{try{await api('/api/logout',{method:'POST'})}catch{}cloudUser=null;if(liveEvents){liveEvents.close();liveEvents=null}setLiveStatus(false);localStorage.removeItem('WSM9_CURRENT');setAuthMode(false);document.getElementById('authModal').classList.add('hidden');toast('Signed out')};
async function resetPasswordFlow(){const email=document.getElementById('authEmail').value.trim();if(!email){toast('Enter your email first');return}try{const r=await api('/api/password-reset/request',{method:'POST',body:JSON.stringify({email})});if(r.devToken){const p=prompt('Development reset token (email delivery is not configured):',r.devToken);if(!p)return;const np=prompt('Enter your new password (8+ characters):');if(!np)return;await api('/api/password-reset/confirm',{method:'POST',body:JSON.stringify({token:p,password:np})});toast('Password reset complete')}else toast(r.message)}catch(e){toast(e.message)}}
async function verifyEmailFlow(){const email=document.getElementById('authEmail').value.trim();if(!email){toast('Enter your email first');return}try{const r=await api('/api/verify-email',{method:'POST',body:JSON.stringify({email})});if(r.devToken){const token=prompt('Development verification token:',r.devToken);if(token){await api('/api/verify-email/confirm',{method:'POST',body:JSON.stringify({token})});toast('Email marked as verified')}}else toast('Verification request prepared')}catch(e){toast(e.message)}}
document.getElementById('resetPasswordBtn').onclick=resetPasswordFlow;document.getElementById('verifyEmailBtn').onclick=verifyEmailFlow;

function openSecurityCenter(){
  if(!current){toast('Sign in first');return}
  document.getElementById('securityModal')?.remove();
  document.body.insertAdjacentHTML('beforeend',`<div id="securityModal" class="modal"><div class="modal-card"><div class="sheet-head"><b>Account security</b><button type="button" onclick="document.getElementById('securityModal').remove()">×</button></div><div id="securityInfo" class="small muted">Loading security status…</div><hr><label>Current password<input id="secCurrent" type="password" autocomplete="current-password"></label><label>New password<input id="secNew" type="password" autocomplete="new-password" placeholder="10+ characters, letters + numbers"></label><button class="primary full" type="button" onclick="changeMyPassword()">Change password</button><button class="secondary full" type="button" onclick="logoutAllSessions()">Sign out all other devices</button><div id="securitySessions" class="small" style="margin-top:12px"></div></div></div>`);
  loadSecurityStatus();
}
async function loadSecurityStatus(){try{const r=await api('/api/security/status');const info=document.getElementById('securityInfo');if(info)info.innerHTML=`Email verified: <b>${r.emailVerified?'Yes':'No'}</b><br>Minimum password length: <b>${r.passwordMin}</b><br>Active sessions: <b>${r.activeSessions}</b>`;const me=await api('/api/me');const box=document.getElementById('securitySessions');if(box)box.innerHTML=(me.sessions||[]).map(x=>`<div class="notification"><div><b>${x.current?'Current device':'Signed-in device'}</b><p>${esc((x.ua||'Unknown device').slice(0,120))}<br>${esc(x.ip||'unknown IP')} • ${timeAgo(x.createdAt)}</p></div>${x.current?'':`<button type="button" onclick="revokeMySession('${esc(x.id)}')">Revoke</button>`}</div>`).join('')||'No active sessions.';}catch(e){const info=document.getElementById('securityInfo');if(info)info.textContent=e.message}}
async function changeMyPassword(){const currentPassword=document.getElementById('secCurrent')?.value||'';const newPassword=document.getElementById('secNew')?.value||'';if(!currentPassword||!newPassword){toast('Enter both passwords');return}try{await api('/api/change-password',{method:'POST',body:JSON.stringify({currentPassword,newPassword})});toast('Password changed. Other sessions were signed out.');document.getElementById('securityModal')?.remove();}catch(e){toast(e.message)}}
async function logoutAllSessions(){try{await api('/api/logout-all',{method:'POST'});toast('All other sessions signed out');await bootstrapCloud();openSecurityCenter()}catch(e){toast(e.message)}}
async function revokeMySession(id){try{await api('/api/sessions/revoke',{method:'POST',body:JSON.stringify({id})});loadSecurityStatus();toast('Session revoked')}catch(e){toast(e.message)}}
document.getElementById('shareAppBtn').onclick=()=>{const text='Join me on WHO SABI ME? — create a quiz and see who really knows you!';if(navigator.share)navigator.share({title:'WHO SABI ME?',text,url:location.origin});else navigator.clipboard?.writeText(location.origin).then(()=>toast('App link copied'))};
async function bootstrapCloud(){try{const data=await api('/api/me');if(data.user){cloudUser=data.user;current=data.user.username;localStorage.setItem('WSM9_CURRENT',current);await pullCloudState();updateChrome();connectLive();const paymentRef=new URLSearchParams(location.search).get('reference');if(paymentRef){try{const pr=await api('/api/economy/verify?reference='+encodeURIComponent(paymentRef));toast(pr.providerStatus==='success'?'Payment confirmed. Coins added.':'Payment status: '+(pr.providerStatus||'pending'));history.replaceState({},'',location.pathname)}catch(e){toast('Payment is still being confirmed. Check your wallet shortly.')}}}}catch(e){setLiveStatus(false)}}
bootstrapCloud();

/* v11 — social graph, comments, private messaging, privacy and moderation */
db.comments=db.comments||[];db.messages=db.messages||[];db.friendRequests=db.friendRequests||[];db.privacy=db.privacy||{};

const v11BaseGo=go;
go=function(id){v11BaseGo(id);if(id==='messages')renderMessages();if(id==='admin')renderAdmin();};

document.getElementById('messageBtn').onclick=()=>{if(!current){toast('Sign in first');return}go('messages')};

function commentsFor(memoryId){return (db.comments||[]).filter(c=>c.memoryId===memoryId).sort((a,b)=>a.createdAt-b.createdAt).slice(-8)}
function commentHtml(c){const p=db.profiles[c.username]||{username:c.username,displayName:c.username};return `<div class="comment-row">${avatar(p)}<div><b>${esc(p.displayName)}</b><span>${esc(c.text)}</span><small>${timeAgo(c.createdAt)}</small></div></div>`}
function enhancedMemoryCard(m){
 const p=db.profiles[m.username]||{username:m.username,displayName:m.username};
 const imgs=(m.photos||[]).map(x=>`<img src="${x}" loading="lazy" alt="Throwback photo">`).join('');
 const r=m.reactions||{};const liked=Boolean(m.likedBy&&m.likedBy.includes(current));const comments=commentsFor(m.id);
 return `<article class="feed-card"><div class="post-head"><button class="brand-btn" style="padding:0" onclick="renderProfile('${esc(m.username)}');go('profile')">${avatar(p)}<span class="post-meta"><b>${esc(p.displayName)}</b><small>@${esc(p.username)} • ${timeAgo(m.createdAt)}</small></span></button><button class="more-btn" onclick="reportItem('memory','${esc(m.id)}')">⋯</button></div>${m.caption?`<div class="post-text">${esc(m.caption)}</div>`:''}<div class="memory-images ${m.photos?.length===1?'one':''}">${imgs}</div><div class="post-actions"><button class="action ${liked?'active':''}" onclick="react('${esc(m.id)}','❤️')">❤️ ${r['❤️']||0}</button><button class="action" onclick="react('${esc(m.id)}','👍')">👍 ${r['👍']||0}</button><button class="action" onclick="react('${esc(m.id)}','😂')">😂 ${r['😂']||0}</button><button class="action" onclick="focusComment('${esc(m.id)}')">💬 ${comments.length}</button><button class="action" onclick="shareMemory('${esc(m.id)}')">↗</button></div><div class="comments" id="comments-${esc(m.id)}">${comments.map(commentHtml).join('')}</div><div class="comment-compose"><input id="comment-${esc(m.id)}" maxlength="500" placeholder="Add a comment…" onkeydown="if(event.key==='Enter')postComment('${esc(m.id)}')"><button onclick="postComment('${esc(m.id)}')">Send</button></div></article>`;
}
memoryCard=enhancedMemoryCard;

function focusComment(id){const el=document.getElementById('comment-'+id);if(el){el.focus();el.scrollIntoView({behavior:'smooth',block:'center'})}}
async function postComment(memoryId){if(!current){toast('Sign in to comment');return}const input=document.getElementById('comment-'+memoryId);const text=input?.value.trim();if(!text)return;try{const data=await api('/api/comments',{method:'POST',body:JSON.stringify({memoryId,text})});db.comments.push(data.comment);save();if(document.getElementById('memoryFeed'))renderMemories();renderHome();toast('Comment added')}catch(e){toast(e.message)}}

function friendState(u){return (db.friendRequests||[]).find(r=>(r.from===current&&r.to===u)||(r.from===u&&r.to===current))}
async function sendFriendRequest(u){try{const data=await api('/api/friend-requests',{method:'POST',body:JSON.stringify({to:u})});db.friendRequests.push(data.request);toast('Friend request sent');renderProfile(u)}catch(e){toast(e.message)}}
async function respondFriend(id,status){try{const data=await api('/api/friend-requests/'+encodeURIComponent(id),{method:'PUT',body:JSON.stringify({status})});const i=db.friendRequests.findIndex(x=>x.id===id);if(i>=0)db.friendRequests[i]=data.request;await pullCloudState();renderNotifications();toast(status==='accepted'?'Friend request accepted':'Request declined')}catch(e){toast(e.message)}}

const v11BaseRenderProfile=renderProfile;
renderProfile=function(u){
 const p=db.profiles[u];if(!p){return v11BaseRenderProfile(u)}
 v11BaseRenderProfile(u);
 const mount=document.getElementById('profileMount');const card=mount.querySelector('.profile-actions');if(!card)return;
 if(u!==current){const req=friendState(u);let friend='';if(req?.status==='accepted')friend='<button disabled>✓ Friends</button>';else if(req?.status==='pending'&&req.from===current)friend='<button disabled>Request sent</button>';else if(req?.status==='pending'&&req.to===current)friend=`<button onclick="respondFriend('${esc(req.id)}','accepted')">✓ Accept request</button>`;else friend=`<button onclick="sendFriendRequest('${esc(u)}')">＋ Friend</button>`;card.insertAdjacentHTML('afterbegin',friend)}
 else {card.insertAdjacentHTML('afterbegin',`<button onclick="openPrivacy()">🔒 Privacy</button>`)}
 card.insertAdjacentHTML('beforeend',`<button onclick="startMessage('${esc(u)}')">💬 Message</button><button onclick="reportItem('profile','${esc(u)}')">⚑ Report</button>`);
};

function startMessage(u){document.getElementById('messageTo').value=u;go('messages');loadThread(u)}
async function loadThread(u){u=(u||'').trim().toLowerCase();if(!u)return;document.getElementById('messageTo').value=u;try{const data=await api('/api/messages?with='+encodeURIComponent(u));db.messages=data.messages;renderThread(u)}catch(e){toast(e.message)}}
function renderThread(u){const box=document.getElementById('messageThread');const msgs=(db.messages||[]).filter(m=>(m.from===current&&m.to===u)||(m.from===u&&m.to===current));box.innerHTML=msgs.length?msgs.map(m=>`<div class="bubble ${m.from===current?'mine':''}"><span>${esc(m.text)}</span><small>${timeAgo(m.createdAt)}</small></div>`).join(''):'<div class="empty">No messages yet. Say hello 👋</div>';box.scrollTop=box.scrollHeight}
document.getElementById('messageTo').addEventListener('change',e=>loadThread(e.target.value));
document.getElementById('sendMessage').onclick=async()=>{const to=document.getElementById('messageTo').value.trim().toLowerCase();const input=document.getElementById('messageText');const text=input.value.trim();if(!to||!text){toast('Enter a username and message');return}try{const data=await api('/api/messages',{method:'POST',body:JSON.stringify({to,text})});db.messages.push(data.message);input.value='';renderThread(to);toast('Message sent')}catch(e){toast(e.message)}};
document.getElementById('messageText').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();document.getElementById('sendMessage').click()}});
let messagePoll=null;setInterval(()=>{if(document.getElementById('messages').classList.contains('active')){const u=document.getElementById('messageTo').value.trim();if(u)loadThread(u)}},5000);

function openPrivacy(){const p=db.privacy[current]||{};const existing=document.getElementById('privacyModal');if(existing)existing.remove();document.body.insertAdjacentHTML('beforeend',`<div id="privacyModal" class="modal"><div class="modal-card"><div class="sheet-head"><b>Privacy settings</b><button onclick="document.getElementById('privacyModal').remove()">×</button></div><label class="switch-row"><span>Private profile<small>Only followers can see your profile details.</small></span><input id="privateProfile" type="checkbox" ${p.private?'checked':''}></label><button class="primary full" onclick="savePrivacy()">Save privacy</button></div></div>`)}
async function savePrivacy(){const value=document.getElementById('privateProfile').checked;try{const data=await api('/api/profile/privacy',{method:'PUT',body:JSON.stringify({private:value})});db.privacy[current]=data.privacy;localSave();document.getElementById('privacyModal').remove();toast(value?'Profile is private':'Profile is public');renderProfile(current)}catch(e){toast(e.message)}}

function reportItem(targetType,targetId){const reason=prompt('Why are you reporting this?');if(!reason?.trim())return;api('/api/report',{method:'POST',body:JSON.stringify({targetType,targetId,reason:reason.trim()})}).then(()=>toast('Report submitted')).catch(e=>toast(e.message))}
async function renderAdmin(){
 const root=document.getElementById('adminRoot'); if(!root)return;
 root.innerHTML=`<div class="admin-tabs"><button class="active" data-at="overview">Overview</button><button data-at="users">Users</button><button data-at="reports">Reports</button><button data-at="games">Live Games</button><button data-at="words">Word Bank</button><button data-at="economy">Economy</button><button data-at="payments">Payments</button><button data-at="ads">Ads</button><button data-at="announcements">Announcements</button><button data-at="appeals">Appeals</button></div><div id="adminPanel"><div class="empty">Loading admin center…</div></div>`;
 const panel=document.getElementById('adminPanel');
 const money=n=>`₦${(Number(n||0)/100).toLocaleString('en-NG',{minimumFractionDigits:2})}`;
 const load=async(tab)=>{
  document.querySelectorAll('[data-at]').forEach(b=>b.classList.toggle('active',b.dataset.at===tab));
  try{
   if(tab==='overview'){const d=await api('/api/admin/overview');panel.innerHTML=`<div class="admin-grid">${Object.entries(d.stats).map(([k,v])=>`<div class="card admin-stat"><small>${esc(k.replace(/([A-Z])/g,' $1'))}</small><b>${esc(String(v))}</b></div>`).join('')}</div><div class="card form-card admin-tools"><b>System tools</b><div class="admin-actions"><button class="secondary" id="adminBackup">Create database backup</button><button class="secondary" id="adminRefresh">Refresh</button></div></div>`;document.getElementById('adminBackup').onclick=async()=>{try{const r=await api('/api/admin/backup',{method:'POST'});toast('Backup created: '+r.file)}catch(e){toast(e.message)}};document.getElementById('adminRefresh').onclick=()=>load('overview');}
   if(tab==='users'){panel.innerHTML=`<div class="card form-card"><div class="admin-row"><input id="adminUserSearch" placeholder="Search username or email…"><button class="secondary" id="findUsers">Search</button></div></div><div id="adminUsers"></div>`;const fetchUsers=async()=>{const q=document.getElementById('adminUserSearch').value.trim();const d=await api('/api/admin/users?q='+encodeURIComponent(q));document.getElementById('adminUsers').innerHTML=d.users.length?d.users.map(u=>`<div class="card admin-item"><div><b>@${esc(u.username)}</b><p>${esc(u.email)} • ${esc(u.status)} • ${timeAgo(u.createdAt)}</p></div><select onchange="adminSetUserStatus('${esc(u.username)}',this.value)"><option value="active" ${u.status==='active'?'selected':''}>Active</option><option value="suspended" ${u.status==='suspended'?'selected':''}>Suspended</option><option value="banned" ${u.status==='banned'?'selected':''}>Banned</option></select></div>`).join(''):'<div class="empty">No users found.</div>'};document.getElementById('findUsers').onclick=fetchUsers;document.getElementById('adminUserSearch').addEventListener('keydown',e=>{if(e.key==='Enter')fetchUsers()});await fetchUsers();}
   if(tab==='reports'){const d=await api('/api/admin/reports');panel.innerHTML=d.reports.length?d.reports.map(r=>`<div class="card admin-item"><div><b>${esc(r.targetType)} report</b><p>By @${esc(r.reporter)} • ${timeAgo(r.createdAt)} • <span class="status-pill">${esc(r.status||'open')}</span></p><small>${esc(r.targetId)} — ${esc(r.reason)}</small></div><select onchange="adminSetReport('${esc(r.id)}',this.value)"><option value="open" ${r.status==='open'?'selected':''}>Open</option><option value="reviewing" ${r.status==='reviewing'?'selected':''}>Reviewing</option><option value="resolved" ${r.status==='resolved'?'selected':''}>Resolved</option><option value="dismissed" ${r.status==='dismissed'?'selected':''}>Dismissed</option></select></div>`).join(''):'<div class="empty">No reports.</div>';}
   if(tab==='games'){const d=await api('/api/admin/games');panel.innerHTML=d.games.length?d.games.map(g=>`<div class="card admin-item"><div><b>Game ${esc(g.roomCode||g.id.slice(0,8))}</b><p>${esc(g.status)} • host @${esc(g.host)} • ${g.players.length} players • ${g.spectators} spectators • ${g.found} words</p></div>${g.status==='playing'?`<button class="danger small-btn" onclick="adminEndGame('${esc(g.id)}')">End game</button>`:'<span class="status-pill">Ended</span>'}</div>`).join(''):'<div class="empty">No puzzle games yet.</div>';}
   if(tab==='words'){const d=await api('/api/admin/words');panel.innerHTML=`<div class="card form-card"><label>Word<input id="newWord" maxlength="30" placeholder="e.g. KNOWLEDGE"></label><div class="admin-row"><select id="wordDifficulty"><option>easy</option><option selected>normal</option><option>hard</option></select><input id="wordCategory" maxlength="40" placeholder="Category"><button class="primary" id="addWord">Add</button></div><p class="small muted">Words are normalized to A–Z and duplicates are ignored.</p></div><div class="word-grid">${d.words.map(w=>`<div class="word-chip"><b>${esc(w.word)}</b><small>${esc(w.category)} • ${esc(w.difficulty)}</small><button onclick="adminDeleteWord('${esc(w.id)}')">×</button></div>`).join('')}</div>`;document.getElementById('addWord').onclick=async()=>{try{await api('/api/admin/words',{method:'POST',body:JSON.stringify({word:document.getElementById('newWord').value,category:document.getElementById('wordCategory').value,difficulty:document.getElementById('wordDifficulty').value})});toast('Word added');load('words')}catch(e){toast(e.message)}};}
   if(tab==='payments'){const d=await api('/api/admin/payments');panel.innerHTML=`<div class="admin-grid"><div class="card admin-stat"><small>Payments</small><b>${d.summary.total}</b></div><div class="card admin-stat"><small>Completed</small><b>${d.summary.completed}</b></div><div class="card admin-stat"><small>Pending</small><b>${d.summary.pending}</b></div><div class="card admin-stat"><small>Gross paid</small><b>${money(d.summary.amountKobo)}</b></div></div><div class="card form-card"><b>Recent coin purchases</b>${d.transactions.map(x=>`<div class="admin-item"><div><b>@${esc(x.username)}</b><p>${esc(x.product||'coin purchase')} • ${esc(x.status)} • ${money(x.amountKobo)} • ${x.coins} coins</p><small>${esc(x.reference||x.id)}</small></div>${x.status==='completed'&&!['pending','processing','processed'].includes(x.refundStatus||'')?`<button class="danger small-btn" onclick="adminRefund('${esc(x.id)}')">Refund</button>`:''}</div>`).join('')||'<div class="empty">No payments yet.</div>'}</div>`;}
   if(tab==='economy'){const d=await api('/api/admin/economy');panel.innerHTML=`<div class="admin-grid"><div class="card admin-stat"><small>Transactions</small><b>${d.summary.transactions}</b></div><div class="card admin-stat"><small>Completed</small><b>${d.summary.completed}</b></div><div class="card admin-stat"><small>Pending</small><b>${d.summary.pending}</b></div><div class="card admin-stat"><small>Recorded revenue</small><b>${money(d.summary.revenueKobo)}</b></div><div class="card admin-stat"><small>Coins issued</small><b>${d.summary.coinsIssued}</b></div></div><div class="card form-card"><b>Recent transactions</b>${d.recent.map(x=>`<div class="admin-mini"><span>@${esc(x.username)} • ${esc(x.type)}</span><span>${esc(x.status)} ${x.amountKobo?money(x.amountKobo):''}</span></div>`).join('')||'<div class="empty">No transactions.</div>'}</div>`;}
   if(tab==='announcements'){const d=await api('/api/admin/announcements');panel.innerHTML=`<div class="card form-card"><label>Title<input id="annTitle" maxlength="100" placeholder="Announcement title"></label><label>Message<textarea id="annMessage" maxlength="1000" placeholder="Write an announcement…"></textarea></label><button class="primary full" id="publishAnn">Publish announcement</button></div>${d.announcements.map(a=>`<div class="card admin-item"><div><b>${esc(a.title)}</b><p>${esc(a.message)}</p><small>${timeAgo(a.createdAt)}</small></div></div>`).join('')}`;document.getElementById('publishAnn').onclick=async()=>{try{await api('/api/admin/announcements',{method:'POST',body:JSON.stringify({title:document.getElementById('annTitle').value,message:document.getElementById('annMessage').value})});toast('Announcement published');load('announcements')}catch(e){toast(e.message)}};}
   if(tab==='appeals'){const d=await api('/api/admin/appeals');panel.innerHTML=d.appeals.length?d.appeals.map(a=>`<div class="card admin-item"><div><b>@${esc(a.username)} appeal</b><p>${esc(a.reason)}</p><small>${timeAgo(a.createdAt)} • ${esc(a.status)}</small></div><select onchange="adminSetAppeal('${esc(a.id)}',this.value)"><option value="open" ${a.status==='open'?'selected':''}>Open</option><option value="approved" ${a.status==='approved'?'selected':''}>Approve</option><option value="rejected" ${a.status==='rejected'?'selected':''}>Reject</option></select></div>`).join(''):'<div class="empty">No appeals.</div>';}
  }catch(e){panel.innerHTML=`<div class="empty">${esc(e.message)}</div>`}
 };
 document.querySelectorAll('[data-at]').forEach(b=>b.onclick=()=>load(b.dataset.at));
 await load('overview');
}
async function adminRefund(id){const amount=prompt('Refund amount in kobo (leave blank for full refund):','');if(amount===null)return;try{await api('/api/admin/payments/'+encodeURIComponent(id)+'/refund',{method:'POST',body:JSON.stringify({amountKobo:amount?Number(amount):undefined})});toast('Refund requested');renderAdmin()}catch(e){toast(e.message)}}
async function adminSetUserStatus(u,status){try{await api('/api/admin/users/'+encodeURIComponent(u),{method:'PUT',body:JSON.stringify({status})});toast('@'+u+' is now '+status);renderAdmin()}catch(e){toast(e.message)}}
async function adminSetReport(id,status){try{await api('/api/admin/reports/'+encodeURIComponent(id),{method:'PUT',body:JSON.stringify({status})});toast('Report updated')}catch(e){toast(e.message)}}
async function adminEndGame(id){if(!confirm('End this live puzzle game?'))return;try{await api('/api/admin/games/'+encodeURIComponent(id)+'/end',{method:'POST'});toast('Game ended');renderAdmin()}catch(e){toast(e.message)}}
