  window.reviewCreatorPack=async(id)=>{const rating=prompt('Rating 1–5:','5');if(!rating)return;const body=prompt('Short review (optional):','')||'';try{await creatorApi('/api/creator/reviews/'+encodeURIComponent(id),{method:'POST',body:JSON.stringify({rating,body})});toast('Review saved');renderCreatorCenter()}catch(e){toast(e.message)}};
